function createSetupButtons()

    if self.memo ~= "0" and self.memo ~= "1" then
        self.createButton({
            label="S", click_function="setup", function_owner=self,
            position={0, 0, 0.75}, rotation={0,0,180}, height=230, width=230,
            font_size=200, color={1,1,1}, font_color={0,0,0}
        })
    end

    if self.memo == "0" or self.memo == "1" then
            self.createButton({
            label="G", click_function="guardian", function_owner=self,
            position={0.75, 0, 0.75}, rotation={0,0,180}, height=230, width=230,
            font_size=200, color={1,1,1}, font_color={0,0,0}
        })
    end

    if self.memo == "0" then
        self.createButton({
            label="Spell", click_function="draw_spell", function_owner=self,
            position={-0.5, 0, -0.75}, rotation={0,0,180}, height=230, width=520,
            font_size=200, color={0,0,0}, font_color={0.5,0.5,0.5}
        })
    end

end

function setup()
    params = { guid = self.guid }
    Global.call("setup_site",params)

    self.memo = "0"
    self.clearButtons()
    createSetupButtons()
end


