function createSetupButtons()

    if self.hasTag("MM") then
        cstring = {1,0,0}
        fstring = {0,0,0}
    elseif self.hasTag("CC") then
        cstring = {0.15,0.15,0.15}
        fstring = {1,1,1}
    elseif self.hasTag("WW") then
        cstring = {0,1,0}
        fstring = {0,0,0}
    elseif self.hasTag("PP") then
        cstring = {0.5,0.5,0.5}
        fstring = {1,1,1}
    elseif self.hasTag("SS") then
        cstring = {1,1,0}
        fstring = {0,0,0}
    elseif self.hasTag("DD") then
        cstring = {1,0.5,0}
        fstring = {1,1,1}
    elseif self.hasTag("RR") then
        cstring = {0,0,1}
        fstring = {1,1,1}
    elseif self.hasTag("TT") then
        cstring = {0.75,0.25,0.75}
        fstring = {1,1,1}
    elseif self.hasTag("HH") then
        cstring = {0.5,0.25,0.125}
        fstring = {1,1,1}
    end

    if self.memo == "0" then

        self.createButton({
            label="M", click_function="buttonClick_M1", function_owner=self,
            position={-0.43, 0.2, 0.74}, rotation={0,30,0}, height=50, width=50,
            font_size=40, color=cstring, font_color=fstring
        })
        self.createButton({
            label="M", click_function="buttonClick_M2", function_owner=self,
            position={0.43, 0, 0.74}, rotation={0,30,180}, height=50, width=50,
            font_size=40, color=cstring, font_color=fstring
        })
        --co-op
        local TokenBags = Global.getTable("TokenBags")
        local SiteBag = getObjectFromGUID(TokenBags["SiteBag"])
        local IsCoop = ""
        if SiteBag then IsCoop = SiteBag.getGMNotes() end
local OutlawBag = getObjectFromGUID(TokenBags["OutlawBag"])
        local _Weather = ""
        if OutlawBag then _Weather = OutlawBag.getGMNotes() end
        if IsCoop == "1" or _Weather == "Primal" then
            --wandering
            self.createButton({
                label="1", click_function="buttonClick_W1", function_owner=self,
                position={-0.61, 0.2, 0.56}, rotation={0,30,0}, height=30, width=30,
                font_size=30, color={1,1,1}, font_color={0,0,0}
            })
            self.createButton({
                label="1", click_function="buttonClick_W2", function_owner=self,
                position={0.61, 0, 0.56}, rotation={0,30,180}, height=30, width=30,
                font_size=30, color={1,1,1}, font_color={0,0,0}
            })
            --local
            self.createButton({
                label="1", click_function="buttonClick_L1", function_owner=self,
                position={-0.17, 0.2, 0.81}, rotation={0,30,0}, height=30, width=30,
                font_size=30, color={1,1,1}, font_color={0,0,0}
            })
            self.createButton({
                label="1", click_function="buttonClick_L2", function_owner=self,
                position={0.17, 0, 0.81}, rotation={0,30,180}, height=30, width=30,
                font_size=30, color={1,1,1}, font_color={0,0,0}
            })
        end
    else
        self.createButton({
            label="W", click_function="buttonClick_W", function_owner=self,
            position={-0.43, 0.2, 0.74}, rotation={0,30,0}, height=50, width=50,
            font_size=36, color=cstring, font_color=fstring
        })
        self.createButton({
