        cstring = {1,0,0}
        fstring = {0,0,0}
    elseif self.hasTag("CC") then
        cstring = {0.15,0.15,0.15}
        fstring = {1,1,1}
    elseif self.hasTag("WW") then
        cstring = {0,1,0}
        fstring = {0,0,0}
    elseif self.hasTag("PP") then
        cstring = {0.5,0.5,0.5}
        fstring = {1,1,1}
    elseif self.hasTag("SS") then
