        fstring = {0,0,0}
    elseif self.hasTag("CC") then
        cstring = {0.15,0.15,0.15}
        fstring = {1,1,1}
    elseif self.hasTag("WW") then
        cstring = {0,1,0}
        fstring = {0,0,0}
    elseif self.hasTag("PP") then
        cstring = {0.5,0.5,0.5}
        fstring = {1,1,1}
    elseif self.hasTag("SS") then
        cstring = {1,1,0}
        fstring = {0,0,0}
    elseif self.hasTag("DD") then
        cstring = {1,0.5,0}
        fstring = {1,1,1}
    elseif self.hasTag("RR") then
        cstring = {0,0,1}
        fstring = {1,1,1}
    elseif self.hasTag("TT") then
        cstring = {0.75,0.25,0.75}
        fstring = {1,1,1}
    elseif self.hasTag("HH") then
        cstring = {0.5,0.25,0.125}
        fstring = {1,1,1}
    end

    if self.memo == "0" then

        self.createButton({
