function createSetupButtons()
    if self.memo == nil then

        if self.hasTag("WW") then
            cstring = {0,1,0}
            fstring = {0,0,0}
        elseif self.hasTag("PP") then
            cstring = {0.5,0.5,0.5}
            fstring = {1,1,1}
        elseif self.hasTag("SS") then
            cstring = {1,1,0}
            fstring = {0,0,0}
        elseif self.hasTag("DD") then
            cstring = {1,0.5,0}
            fstring = {1,1,1}
        elseif self.hasTag("TT") then
            cstring = {0.75,0.25,0.75}
            fstring = {1,1,1}
        end

        self.createButton({
            label="W", click_function="buttonClick_W", function_owner=self,
            position={0, 0.1, 0.75}, rotation={0,0,0}, height=220, width=220,
            font_size=200, color=cstring, font_color=fstring
