function return_die(player_color, index, guid) 
    local coPDice = Global.getTable("coDicePlayers")               
    local coDice = coPDice[player_color]               
    local coDie = coDice[index]

    local Die = getObjectFromGUID(guid)
    local DieValue = Die.getValue()

     local yrot = 0
    if player_color == "Blue" or player_color == "Yellow" or player_color == "Pink" then yrot = 180 end
    --if player_color == "xxPink" or player_color == "xxPurple" then yrot = 90 end
    
    local DieRotation = {
        Vector(270,yrot,0),
        Vector(0,yrot,0),
        Vector(0,yrot,270),
        Vector(0,yrot,90),
        Vector(0,yrot,180),
        Vector(90,yrot,0),
    }    if Die ~= nil then
        Die.setRotationSmooth(DieRotation[DieValue])
        Die.setPositionSmooth({coDie[1],2,coDie[2]})
    end
end

function die_results(player_color, type, guid)
    local Die = getObjectFromGUID(guid)
    if Die ~= nil then
        if type == "S" then
            local message_color = Color(0.85, 0.85, 0.85)
            local messages = {
                " found nothing",
                " found clues",
                " found clues",
                " found nothing",
                " found clues",
                " found nothing"
            }
            local message = messages[Die.getValue()]
            broadcastToAll(player_color .. " player" .. message, message_color)
